// Plain language (TP-0) — the words the user sees, in one place.
//
// Kevin: "Numbers are fine — acronyms and jargon are hard to follow." Every
// screen and every line the coach is told to quote speaks in these terms;
// internal identifiers (isDeloadTarget, rung, intent.mode === 'deload') keep
// their names — renaming code buys the user nothing.
//
// Pure. Imports only mirrored siblings.
//
// MIRRORED: functions/plain-language.js is generated by
//   node scripts/sync-mirror.mjs js/core/features/plain-language.js functions/plain-language.js
// (tests/unit/movement-patterns-mirror.test.js enforces parity).

import { isDeloadTarget, weekTargetEffects } from './week-targets.js';

/** The user's words, and the jargon each one replaces (docs/training-plan-design-2026-10.md §1.1). */
export const TERMS = {
    plan: { short: 'plan', long: 'your training for the next few months, and how it moves toward your goals', replaces: ['program', 'block'] },
    lighterWeek: { short: 'lighter week', long: 'a planned week at reduced load', replaces: ['deload'] },
    buildWeek: { short: 'build week', long: 'a normal week that adds a little work', replaces: ['accumulate'] },
    pushWeek: { short: 'push week', long: 'a normal week that goes a little heavier', replaces: ['intensify'] },
    mainLifts: { short: 'main lifts', long: 'the exercises your plan tracks strength on', replaces: ['primaries'] },
    estimatedMax: { short: 'estimated max', long: 'what you could probably lift once, worked out from your sets', replaces: ['e1RM'] },
    effort: { short: 'effort', long: 'how hard a set felt, out of 10', replaces: ['RPE'] },
    stuck: { short: 'stuck', long: 'three or more sessions without progress at a weight', replaces: ['stall', 'rung'] },
    enoughWork: { short: 'enough', long: 'weekly sets for a muscle — enough for it to grow', replaces: ['MEV'] },
    tooMuchWork: { short: 'more than it can use', long: 'weekly sets beyond what a muscle can recover from', replaces: ['MRV'] },
};

/**
 * Words that never reach a screen or a line the coach quotes. Whole-word
 * ("blocked" isn't "block"); RPE / MEV / MRV are matched upper-case only.
 */
const BANNED = [
    ['e1RM', /\be?1RMs?\b/gi],
    ['RPE', /\bRPE\b/g],
    ['MEV', /\bMEV\b/g],
    ['MRV', /\bMRV\b/g],
    ['rung', /\brungs?\b/gi],
    ['deload', /\bdeload(?:s|ed|ing)?\b/gi],
    ['block', /\bblocks?\b/gi],
    ['accumulate', /\baccumulat(?:e|es|ed|ing|ion)\b/gi],
    ['intensify', /\bintensif(?:y|ies|ied|ying|ication)\b/gi],
    ['hypertrophy', /\bhypertrophy\b/gi],
    ['periodization', /\bperiodi[sz]ation\b/gi],
    ['primaries', /\bprimaries\b/gi],
];

export const BANNED_UI_TERMS = BANNED.map(([term]) => term);

/**
 * Every banned term in `text`, in order of appearance.
 * @param {string} text
 * @param {{allow?: string[]}} [opts] - terms to skip (e.g. the user asked "what's RPE?")
 * @returns {{term: string, match: string, index: number}[]}
 */
export function findJargon(text, { allow = [] } = {}) {
    const skip = new Set(allow);
    const out = [];
    const s = String(text || '');
    for (const [term, re] of BANNED) {
        if (skip.has(term)) continue;
        re.lastIndex = 0;
        let m;
        while ((m = re.exec(s))) out.push({ term, match: m[0], index: m.index });
    }
    return out.sort((a, b) => a.index - b.index);
}

/** The banned terms a piece of text uses — for "the user asked about it" exemptions. */
export function jargonTermsIn(text) {
    return [...new Set(findJargon(text).map(j => j.term))];
}

// ── Formatters: numbers in, sentences out ───────────────────────────

const round = (n) => Math.round(n);
const signed = (n) => `${n > 0 ? '+' : n < 0 ? '−' : ''}${Math.abs(n)}`;

/** Effort for one set: "effort 8/10". '' when there is no rating. */
export function effortTag(rpe) {
    const n = Number(rpe);
    if (rpe == null || rpe === '' || !Number.isFinite(n)) return '';
    return `effort ${n}/10`;
}

/** Effort in a sentence: "effort 9 of 10". */
export function describeEffort(rpe) {
    const n = Number(rpe);
    if (rpe == null || rpe === '' || !Number.isFinite(n)) return '';
    return `effort ${n} of 10`;
}

/**
 * 'lighter' | 'peak' | 'push' | 'build' — what kind of week a program target
 * is. "Lighter" follows the levers alone (isDeloadTarget — the same test the
 * session intent uses), so a week never reads lighter while the set rows
 * build; the model's free-text label only tells peak / push / build apart.
 */
export function weekKindOf(target) {
    if (!target) return 'build';
    if (isDeloadTarget(target)) return 'lighter';
    const label = String(target.label || '');
    if (/peak|taper|test|realiz/i.test(label)) return 'peak';
    const { weightPct, rpeTarget } = weekTargetEffects(target);
    if (/intens|heavy|push|strength/i.test(label) || (weightPct != null && weightPct > 0) || (rpeTarget != null && rpeTarget >= 8.5)) return 'push';
    return 'build';
}

const WEEK_KIND_LABEL = { build: 'Build week', push: 'Push week', peak: 'Peak week', lighter: 'Lighter week' };

/** "Build week" / "Push week" / "Peak week" / "Lighter week" — no numbers. */
export function weekKindLabel(target) {
    return WEEK_KIND_LABEL[weekKindOf(target)];
}

/** "Build week" · "Push week" · "Peak week" · "Lighter week (−35%)". */
export function describeWeekKind(target) {
    const kind = weekKindOf(target);
    const base = WEEK_KIND_LABEL[kind];
    if (kind !== 'lighter') return base;
    const { weightPct } = weekTargetEffects(target);
    return weightPct != null && weightPct < 0 ? `${base} (${signed(weightPct)}%)` : base;
}

/**
 * The stall ladder in words. rung 0 → ''.
 *   1 "stuck at 185 lbs for 3 sessions — chase one more rep"
 *   2 "stuck for 4 sessions — backing off to reset"
 *   3 "stuck at 185 lbs for 6 sessions — time to rotate this exercise"
 */
export function describeStuck({ rung = 0, stallRun = null, weight = null, unit = 'lbs' } = {}) {
    if (!rung) return '';
    const n = stallRun ? ` for ${stallRun} sessions` : '';
    const at = weight != null ? ` at ${weight} ${unit}` : '';
    if (rung === 1) return `stuck${at}${n} — chase one more rep`;
    if (rung === 2) return `stuck${n} — backing off to reset`;
    return `stuck${at}${n} — time to rotate this exercise`;
}

/**
 * A progression verdict's action in words (progression.js PROGRESSION_ACTIONS —
 * the test keeps the two lists in step; a new action needs a phrase here).
 */
export const ACTION_WORDS = {
    bump: 'go up',
    consolidate: 'hold',
    'chase-rep': 'chase a rep',
    'back-off': 'back off',
    rotate: 'rotate',
    start: 'start',
    deload: 'lighter',
    reacquaint: 'ease back in',
};

export function describeAction(action) {
    return ACTION_WORDS[action] || String(action || '');
}

/** 'under' | 'enough' | 'over' for a muscle's weekly sets against the app's landmarks. */
export function volumeStatus(sets, { mev, mrv }) {
    if (sets > mrv) return 'over';
    if (sets < mev) return 'under';
    return 'enough';
}

const VOLUME_WORDS = { under: 'under what it needs', enough: 'enough', over: 'more than it can use' };

/** "Chest: 12 sets this week — enough" / "4 sets — under what it needs" / "26 — more than it can use". */
export function describeVolume({ muscle, sets, mev, mrv, period = 'this week' }) {
    const status = volumeStatus(sets, { mev, mrv });
    return `${muscle}: ${sets} set${sets === 1 ? '' : 's'} ${period} — ${VOLUME_WORDS[status]}`;
}

/** The landmarks themselves, for the coach: what "enough" and "too much" mean in sets. */
export function describeVolumeLandmarks({ mev, mrv }) {
    return `Weekly sets per muscle: under ${mev} is less than it needs to grow; over ${mrv} is more than it can recover from`;
}

/** Whole-percent change, or null without a base. */
export function pctChange(now, prev) {
    if (!(prev > 0) || now == null) return null;
    return round(((now - prev) / prev) * 100);
}

/**
 * "Bench press (Smith): estimated max 213 lbs, up 4% from a month ago".
 * `since` names the comparison window ("a month ago", "the 4 weeks before").
 */
export function describeStrengthChange({ name, machine = null, now, prev = null, unit = 'lbs', since = 'a month ago' }) {
    const who = machine ? `${name} (${machine})` : name;
    if (now == null) return `${who}: no recent sets`;
    const head = `${who}: estimated max ${now} ${unit}`;
    const pct = pctChange(now, prev);
    if (pct == null) return head;
    if (pct === 0) return `${head}, about the same as ${since}`;
    return `${head}, ${pct > 0 ? 'up' : 'down'} ${Math.abs(pct)}% from ${since}`;
}
